"""Medien von einer URL holen, ohne dass der Server zum Sprungbrett ins eigene Netz wird."""

import http.client
import ipaddress
import socket
import ssl
from pathlib import PurePosixPath
from urllib.parse import unquote, urljoin, urlsplit

from .library import MediaError

TIMEOUT_S = 20
MAX_REDIRECTS = 5


def _public_ip(host: str, port: int) -> str:
    try:
        infos = socket.getaddrinfo(host, port, type=socket.SOCK_STREAM)
    except (socket.gaierror, UnicodeError):
        raise MediaError(f"Adresse „{host}“ nicht gefunden.") from None
    addresses = {info[4][0] for info in infos}
    # Alle Adressen prüfen: sonst reicht ein DNS-Eintrag mit einer öffentlichen und einer internen IP.
    for address in addresses:
        ip = ipaddress.ip_address(address.split("%")[0])
        if not ip.is_global or ip.is_multicast:
            raise MediaError("Adressen im lokalen oder privaten Netz sind für den Import gesperrt.")
    return sorted(addresses)[0]


class _PinnedHTTPS(http.client.HTTPSConnection):
    """Verbindet zur geprüften IP, prüft das Zertifikat aber gegen den Hostnamen."""

    def __init__(self, ip: str, host: str, port: int):
        super().__init__(host, port, timeout=TIMEOUT_S, context=ssl.create_default_context())
        self.ip = ip

    def connect(self) -> None:
        sock = socket.create_connection((self.ip, self.port), self.timeout)
        self.sock = self._context.wrap_socket(sock, server_hostname=self.host)


def fetch(url: str, limit: int) -> tuple[bytes, str, str]:
    """Liefert Inhalt, Content-Type und einen Namen aus dem Pfad."""
    for _ in range(MAX_REDIRECTS + 1):
        parts = urlsplit(url.strip())
        if parts.scheme not in ("http", "https") or not parts.hostname:
            raise MediaError("Nur http:// und https://-Adressen sind erlaubt.")
        if parts.username or parts.password:
            raise MediaError("Adressen mit Zugangsdaten sind nicht erlaubt.")
        try:
            port = parts.port or (443 if parts.scheme == "https" else 80)
        except ValueError:
            raise MediaError("Ungültiger Port in der Adresse.") from None
        ip = _public_ip(parts.hostname, port)
        if parts.scheme == "https":
            conn = _PinnedHTTPS(ip, parts.hostname, port)
        else:
            # Gleich zur geprüften IP verbinden; ein zweites DNS-Auflösen könnte anders antworten.
            conn = http.client.HTTPConnection(f"[{ip}]" if ":" in ip else ip, port, timeout=TIMEOUT_S)
        path = parts.path or "/"
        if parts.query:
            path += "?" + parts.query
        try:
            conn.request("GET", path, headers={"Host": parts.netloc, "User-Agent": "Hebocon/1.0",
                                               "Accept": "audio/*,video/*,image/*"})
            response = conn.getresponse()
            if response.status in (301, 302, 303, 307, 308) and response.getheader("location"):
                url = urljoin(url, response.getheader("location"))
                continue
            if response.status != 200:
                raise MediaError(f"Server antwortet mit {response.status} {response.reason}.")
            if int(response.getheader("content-length") or 0) > limit:
                raise MediaError("Datei größer als 100 MB.")
            body = response.read(limit + 1)
        except (OSError, http.client.HTTPException) as exc:
            raise MediaError(f"Download fehlgeschlagen: {exc}") from None
        finally:
            conn.close()
        if len(body) > limit:
            raise MediaError("Datei größer als 100 MB.")
        if not body:
            raise MediaError("Die Adresse liefert eine leere Datei.")
        mime = (response.getheader("content-type") or "").split(";")[0].strip().lower()
        name = PurePosixPath(unquote(parts.path)).name or parts.hostname
        return body, mime, name
    raise MediaError("Zu viele Weiterleitungen.")
